    }

    // Send the batch
    console.log(`\nSending batch with ${batch.count} events...`);
    await producerClient.sendBatch(batch);
    console.log(`Successfully sent ${batch.count} events!\n`);
  } catch (error) {
    console.error("Error sending events:", error);
    throw error;
  }
}

